739: /// `Find-CodexProcesses` over a given process list (pure). `since_text` is the pre-formatted
740: /// "started at or after" stamp for the message; `since` is the same instant for the comparison.
741: /// With a bridge pid on Windows, a process counts when its parent is that pid and it started at or
742: /// after `since` (and, if the pid was reused by a live process, before that reuse). Otherwise the
743: /// machine-wide "looks like codex" rule applies (labelled "task not verifiable"); (wave 29, E27) the
744: /// Codex desktop app's servers and helpers ([`codex_server_exclusion`]) are left out and named in
745: /// `check` ("excluded: pid N codex.exe [codex app-server]", at most 6, then "(+k more)") and in
746: /// `excluded`. This process and its ancestors are never counted. (wave 3c, F23-2) A row whose start
747: /// time could not be read (`created: None`) is never skipped: it counts as started at or after
748: /// `since` (and before a reuse of the bridge's pid), its rule says so ([`START_UNREADABLE_COUNTED`]).
749: /// (wave 3e, F30-1) By parent, the whole subtree under the bridge's pid counts, whatever its names:
750: /// a grandchild below a live intermediate too (`descendant of the interrupted bridge pid <p> (ppid
751: /// <q>)`); a link is left out only on positive evidence that it is not the tree's - a row (with its
752: /// subtree) that started before `since`, after a reuse of the bridge's pid, or before its own
753: /// listed parent (that pid's earlier owner was its parent); a start time that cannot be read proves
754: /// nothing, so the walk goes through it. Machine-wide, a row whose start time cannot be read and
755: /// that is not codex-like counts unless its command line is READABLE ([`unproven_identity`]):
756: /// `<what>, task not verifiable; its start time cannot be read - counted (fail-closed)`. The idle
757: /// process (pid 0) is never a candidate. C3's table reads every start time as the plugin's
758: /// `Win32_Process.CreationDate` does (`NtQuerySystemInformation`); one it cannot read must never
759: /// release a record by being skipped.
760: #[allow(clippy::too_many_arguments)]
761: pub fn find_codex_processes(
762:     procs: &[ScanProc],
763:     since: chrono::DateTime<chrono::Utc>,
764:     since_text: &str,
765:     launcher: &str,
766:     bridge_pid: u32,
767:     self_pid: u32,
768:     on_windows: bool,
769: ) -> ScanOutcome {
770:     let by_parent = on_windows && bridge_pid > 0;
771:     let rules = if by_parent {
772:         format!("children of the interrupted bridge pid {bridge_pid}")
773:     } else {
774:         "name codex*, or a command line containing the recorded launcher or @openai/codex; not the Codex app's servers and helpers"
775:             .to_string()
776:     };
777:     let scanner = if on_windows {
778:         "Win32_Process scan"
779:     } else {
780:         "ps scan"
781:     };
782:     let mut check = format!("{scanner} ({rules}; started at or after {since_text})");
783: 
784:     use std::collections::{HashMap, HashSet};
785:     let by_id: HashMap<u32, &ScanProc> = procs.iter().map(|p| (p.pid, p)).collect();
786:     // Never count ourselves or our ancestors (a shell that started this run may carry the launcher
787:     // path on its command line).
788:     let mut excluded: HashSet<u32> = HashSet::new();
789:     let mut cur = self_pid;
790:     let mut guard = 0;
791:     while guard < 64 && cur > 0 && !excluded.contains(&cur) {
792:         excluded.insert(cur);
793:         match by_id.get(&cur) {
794:             Some(p) => cur = p.ppid,
795:             None => break,
796:         }
797:         guard += 1;
798:     }
799: 
800:     // (wave 3e, F30-1) the idle process (pid 0, no start time, no command line) is not a process
801:     // of anyone's tree
802:     excluded.insert(0);
803: 
804:     let mut found = Vec::new();
805:     let mut app_servers: Vec<ExcludedProc> = Vec::new();
806:     if by_parent {
807:         // A live process holding the bridge's pid now is a reuse; only children created before it
808:         // started are ours.
809:         let reused_at = by_id.get(&bridge_pid).and_then(|p| p.created);
810:         // (wave 3e, F30-1) the subtree under the bridge's pid, breadth first in table order (its
811:         // children first): every row under it counts whatever its name - only positive evidence
812:         // that a link is not the tree's leaves a row (and what hangs below it) out
813:         let mut children: HashMap<u32, Vec<&ScanProc>> = HashMap::new();
814:         for p in procs {
815:             children.entry(p.ppid).or_default().push(p);
816:         }
817:         let mut seen: HashSet<u32> = HashSet::from([bridge_pid]);
818:         let mut level: Vec<(u32, Option<chrono::DateTime<chrono::Utc>>)> = vec![(bridge_pid, None)];
819:         let mut depth = 0;
820:         while !level.is_empty() {
821:             depth += 1;
822:             let mut next = Vec::new();
823:             for (parent, parent_created) in level {
824:                 for p in children.get(&parent).map(Vec::as_slice).unwrap_or_default() {
825:                     if excluded.contains(&p.pid) || !seen.insert(p.pid) {
826:                         continue;
827:                     }
828:                     if let Some(c) = p.created {
829:                         // started before the run: not of its tree (nor is anything below it)
830:                         if c < since {
831:                             continue;
832:                         }
833:                         // a child of the process that reused the bridge's pid
834:                         if depth == 1 && reused_at.is_some_and(|r| c >= r) {
835:                             continue;
836:                         }
837:                         // started before its listed parent: that pid's earlier owner was its parent
838:                         if parent_created.is_some_and(|pc| c < pc) {
839:                             continue;
840:                         }
841:                     }
842:                     // (wave 3c, F23-2) a start time that cannot be read is never filtered out: it
843:                     // may have started at or after `since` and before any reuse (fail-closed)
844:                     let unknown = if p.created.is_none() {
845:                         format!("; {START_UNREADABLE_COUNTED}")
846:                     } else {
847:                         String::new()
848:                     };
849:                     let rule = if depth == 1 {
850:                         format!("child of the interrupted bridge (ppid {bridge_pid}){unknown}")
851:                     } else {
852:                         format!(
853:                             "descendant of the interrupted bridge pid {bridge_pid} (ppid {parent}){unknown}"
854:                         )
855:                     };
856:                     found.push(FoundProc {
857:                         pid: p.pid,
858:                         name: p.name.clone(),
859:                         rule,
860:                     });
861:                     next.push((p.pid, p.created));
862:                 }
863:             }
864:             level = next;
865:         }
866:     } else {
