548: /// `p` as the child resolves it: against the child's working directory (the repository root)
549: /// when relative, `.` and `..` folded lexically (as `path.join` does).
550: fn in_child_cwd(repo_root: &Path, p: &str) -> PathBuf {
551:     let p = Path::new(p);
552:     let full = if p.is_absolute() {
553:         p.to_path_buf()
554:     } else {
555:         repo_root.join(p)
556:     };
557:     let mut out = PathBuf::new();
558:     for c in full.components() {
559:         match c {
560:             std::path::Component::CurDir => {}
561:             std::path::Component::ParentDir => {
562:                 out.pop();
563:             }
564:             other => out.push(other.as_os_str()),
565:         }
566:     }
567:     out
568: }
