570: /// Whether `p` lies inside `root` (or is it): lexically, as `Get-RepoRelativePath` decides (a
571: /// relative `p` against the current directory), or (wave 4f, F25-2) once the links on the way are
572: /// resolved - the deepest existing ancestor of `p` and the root canonicalised - so a junction or a
573: /// symbolic link into the repository is caught too.
574: pub fn path_inside(root: &Path, p: &Path) -> bool {
575:     let full = if p.is_absolute() {
576:         p.to_path_buf()
577:     } else {
578:         std::env::current_dir().unwrap_or_default().join(p)
579:     };
580:     if c3_core::paths::repo_relative(root, &full).is_some() {
581:         return true;
582:     }
583:     match (resolve_existing(root), resolve_existing(&full)) {
584:         (Some(r), Some(f)) => c3_core::paths::repo_relative(&r, &f).is_some(),
585:         _ => false,
586:     }
587: }
