+    let roster = e.roster(r#"{"roster_version":1,"reviewers":[{"provider":"ZAI-claude","engine":"claude","model":"glm-5.3","auth":"endpoint","endpoint":{"base_url":"https://api.z.ai/api/anthropic","env_key":"W7_FAKE_ZAI_TOKEN"},"plan":"zai"}]}"#);
